fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    // Iterate p from 0 to n-2, and for each p iterate q from p+1 to n-1.
    // The first time we find nums[p] + nums[q] == target, that pair (p, q)
    // is lexicographically smallest by construction.
    for p in 0..n {
        for q in (p + 1)..n {
            if nums[p] + nums[q] == target {
                return (p, q);
            }
        }
    }
    // By problem assumption, there is always at least one valid pair.
    unreachable!("No two indices sum to the target");
}

